import requests

BASE_URL = "https://api.socbench.example"
product = {
    "name": "Newly Designed Product",
    "category": "personal care",
    "ingredients": [],
    "order_id": "associated-order-id",
}

validation_response = requests.post(
    f"{BASE_URL}/regulation-check",
    json=product,
)
validation_response.raise_for_status()
validation = validation_response.json()

sustainability_response = requests.post(
    f"{BASE_URL}/sustainability-assessment",
    json=product,
)
sustainability_response.raise_for_status()
sustainability = sustainability_response.json()

report_response = requests.get(f"{BASE_URL}/reports/compliance")
report_response.raise_for_status()
report = report_response.json()

def is_non_compliant(data):
    if isinstance(data, dict):
        for key, value in data.items():
            if key.lower() in {"compliant", "is_compliant", "compliance_status", "status"}:
                if value is False or (
                    isinstance(value, str)
                    and value.lower() in {"non-compliant", "noncompliant", "failed"}
                ):
                    return True
            if is_non_compliant(value):
                return True
    elif isinstance(data, list):
        return any(is_non_compliant(item) for item in data)
    return False

if is_non_compliant(validation) or is_non_compliant(report):
    order_id = product.get("order_id")
    if order_id:
        cancel_response = requests.delete(f"{BASE_URL}/orders/{order_id}")
        cancel_response.raise_for_status()

import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

# Supply the inventory manager's updated contact details.
contact_info = {
    "name": os.getenv("INVENTORY_MANAGER_NAME", ""),
    "email": os.getenv("INVENTORY_MANAGER_EMAIL", ""),
    "phone": os.getenv("INVENTORY_MANAGER_PHONE", ""),
}
contact_response = session.patch(
    f"{BASE_URL}/update_contact_info",
    json=contact_info,
)
contact_response.raise_for_status()

# Supply the questionnaire identifier and the responses to submit.
questionnaire_responses = {
    "questionnaireId": os.getenv("QUESTIONNAIRE_ID", ""),
    "responses": [],
}
responses_response = session.post(
    f"{BASE_URL}/responses",
    json=questionnaire_responses,
)
responses_response.raise_for_status()

# Retrieve low-stock medications and create a replenishment order for them.
low_stock_response = session.get(f"{BASE_URL}/inventory/low-stock")
low_stock_response.raise_for_status()
low_stock_data = low_stock_response.json()

medications = (
    low_stock_data
    if isinstance(low_stock_data, list)
    else low_stock_data.get("medications", [])
)

order_items = [
    {
        "medicationId": medication["medicationId"],
        "quantity": medication.get("reorderQuantity", medication.get("quantity", 0)),
    }
    for medication in medications
    if medication.get("medicationId")
]

if order_items:
    order_response = session.post(
        f"{BASE_URL}/orders/new",
        json={"medications": order_items},
    )
    order_response.raise_for_status()

# Remove medications explicitly marked for removal.
medication_ids_to_remove = [
    medication_id
    for medication_id in os.getenv("MEDICATION_IDS_TO_REMOVE", "").split(",")
    if medication_id.strip()
]

for medication_id in medication_ids_to_remove:
    remove_response = session.delete(
        f"{BASE_URL}/inventory/remove/{medication_id.strip()}"
    )
    remove_response.raise_for_status()

